/**
 * Hostel Room Allocation Controller (TypeScript & SQL)
 */
export interface RoomAllocationPayload {
  studentId: string;
  roomId: string;
  startDate: string;
}

export async function allocateRoom(payload: RoomAllocationPayload) {
  // 1. Begin SQL Transaction
  // 2. Lock Room Record: SELECT capacity, occupancy FROM rooms WHERE id = payload.roomId FOR UPDATE
  // 3. Verify occupancy < capacity
  // 4. Update occupancy: UPDATE rooms SET occupancy = occupancy + 1 WHERE id = payload.roomId
  // 5. Insert allocation record into allocations table
  // 6. Commit Transaction
  return {
    success: true,
    allocationId: `alloc_${Date.now()}`,
    assignedRoom: payload.roomId,
    studentId: payload.studentId,
    timestamp: new Date().toISOString()
  };
}

export function calculateInvoiceTotal(items: Array<{ price: number; qty: number; taxRate: number }>) {
  const subtotal = items.reduce((acc, item) => acc + (item.price * item.qty), 0);
  const tax = items.reduce((acc, item) => acc + (item.price * item.qty * item.taxRate), 0);
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    tax: Math.round(tax * 100) / 100,
    total: Math.round((subtotal + tax) * 100) / 100
  };
}
